<?php defined('BASEPATH') or exit('No direct script access allowed'); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo html_escape($title); ?></title><link rel="stylesheet" href="<?php echo module_dir_url('recruitment','assets/css/smart_choice_job_application.css'); ?>?v=1840"></head><body><div class="sc-public-language"><a href="<?php echo current_url(); ?>?lang=english">English</a><a href="<?php echo current_url(); ?>?lang=spanish">Español</a></div><div class="sc-job-page"><div class="sc-job-shell"><div class="sc-job-card"><header class="sc-job-header"><div class="sc-job-brand"><div class="sc-job-logo"><?php echo get_dark_company_logo(); ?></div><div><h1><?php echo _l('recruitment_skill_test_title'); ?></h1><p><?php echo _l('recruitment_skill_test_intro'); ?></p></div></div></header><main class="sc-job-body"><?php if($submitted): ?><div class="sc-success"><div class="sc-success-icon">✓</div><h2><?php echo _l('recruitment_skill_test_complete'); ?></h2><p><?php echo _l('recruitment_skill_test_score', $score, $correct, $total); ?></p></div><?php else: ?><?php echo form_open(current_url()); ?><div class="sc-job-notice"><?php echo _l('recruitment_skill_test_notice'); ?></div><?php foreach($questions as $i=>$q): ?><section class="sc-section"><h2><?php echo ($i+1).'. '._l($q['question']); ?></h2><div class="sc-pills"><?php foreach($q['options'] as $value=>$label): ?><label><input required type="radio" name="answers[<?php echo $i; ?>]" value="<?php echo $value; ?>"><span><?php echo _l($label); ?></span></label><?php endforeach; ?></div></section><?php endforeach; ?><div class="sc-actions"><button class="sc-btn sc-btn-orange" type="submit"><?php echo _l('recruitment_submit_skill_test'); ?></button></div><?php echo form_close(); ?><?php endif; ?></main></div></div></div></body></html>